"""Build a static preproduction board from the current timeline and crop atlas."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parent.parent
TIMELINE = json.loads((ROOT / 'storyboard.json').read_text())
CROPS = json.loads((ROOT / 'assets/components/crop-map.json').read_text())['crops']

def escape(value):
    return html.escape(str(value), quote=True)

def asset(path, alt, class_name=''):
    return f'<img class="{class_name}" src="../{escape(path)}" alt="{escape(alt)}">'

def timestamp(seconds):
    return f'{seconds // 60:02d}:{seconds % 60:02d}'

cards = []
for scene in TIMELINE['scenes']:
    scene_id = scene['id']
    if scene_id == 'S01':
        panel = '<div class="title-frame"><p>One more<br><span>try.</span></p>' + asset('assets/brand/brand-mark.png', 'Existing Ichido ribbon mark') + '</div>'
    elif scene_id == 'S07':
        panel = '<div class="privacy-frame"><p>No account.<br>No recording uploads.<br>No analytics.</p><small>Update checks and optional model downloads use the network.</small></div>'
    elif scene_id == 'S08':
        panel = '<div class="end-frame">' + asset('assets/brand/ichido-wordmark.svg', 'ichido.') + '<p>Get Ichido for Mac</p><small>Free while in early access · macOS 26+</small></div>'
    else:
        panel = '<div class="product-frame">' + asset(scene['review_image'], scene['title'] + ' actual source crop') + '</div>'
    cards.append(f'''<article class="shot"><div class="meta"><span>{escape(scene_id)} · {escape(scene['title'])}</span><span>{timestamp(scene['start_seconds'])}–{timestamp(scene['end_seconds'])}</span></div><div class="frame">{panel}</div><h3>{escape(scene['on_screen_copy'][0])}</h3><p>{escape(scene['visual_plan'])}</p><details><summary>Interaction and voiceover</summary><p>{escape(scene['interaction_plan'])}</p><p class="vo">{escape(scene['voiceover_draft'])}</p></details></article>''')

atlas = []
for crop in CROPS:
    atlas.append('<a class="crop" href="../' + escape(crop['path']) + '">' + asset(crop['path'], crop['notes']) + '<span>' + escape(crop['id']) + ' <small>' + '×'.join(map(str, crop['crop_dimensions'])) + '</small></span></a>')

links = [('script.md','Script'),('interaction_plan.json','Action / response plan'),('assets_manifest.md','Curated assets'),('capture_plan.md','Capture gaps & fallback'),('handoff/OPUS_BRIEF.md','Opus handoff'),('handoff/GEMINI_AUDIO_BRIEF.md','Gemini music brief'),('research/reference_videos.md','Reference analysis'),('product_facts.md','Product facts'),('handoff/website_integration.md','Website replacement')]
styles = '''
@font-face{font-family:Space;src:url('../assets/fonts/space-grotesk-bold.ttf');font-weight:700;font-display:swap}
@font-face{font-family:DM;src:url('../assets/fonts/dm-sans.ttf');font-weight:400;font-display:swap}
:root{--paper:#f4f1e9;--bright:#fbf8ef;--ink:#1f241f;--blue:#2848e8;--line:#d3d1c6}*{box-sizing:border-box}
body{margin:0;color:var(--ink);background:var(--paper);font:17px/1.5 DM,sans-serif}a{color:inherit;text-underline-offset:4px}a:hover{color:var(--blue)}a:focus-visible,summary:focus-visible{outline:3px solid var(--blue);outline-offset:5px}.wrap{max-width:1440px;padding:0 48px;margin:auto}header{display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid var(--line);padding:24px 0}.brand{font:700 32px/1 Space,sans-serif;letter-spacing:-.05em;text-decoration:none}.brand span{color:var(--blue)}nav{display:flex;gap:24px;font-size:14px}.eyebrow{text-transform:uppercase;letter-spacing:.14em;font-size:12px}.hero{display:grid;grid-template-columns:1.4fr 1fr;align-items:center;gap:48px;padding:58px 0 40px}.hero h1{font:700 clamp(64px,7.4vw,108px)/.96 Space,sans-serif;letter-spacing:-.055em;margin:24px 0}.hero h1 span{color:var(--blue)}.hero .intro{max-width:650px;font-size:20px}.hero-visual{background:var(--bright);border-radius:20px;padding:36px;box-shadow:0 8px 24px #1f241f08}.hero-visual .step{font-size:12px;text-transform:uppercase;letter-spacing:.12em;color:#60665c;margin:18px 0 10px}.hero-visual img{display:block;width:100%;border-radius:5px}.hero-visual .arrow{font:700 32px Space,sans-serif;text-align:center;margin:12px;color:var(--blue)}.hero-visual .pointer-row{position:relative}.pointer-row .cursor{position:absolute;width:25px;right:35%;bottom:-12px;filter:drop-shadow(0 2px 2px #0004)}.pill{display:inline-block;border:1px solid var(--line);padding:5px 12px;border-radius:99px;margin:0 6px 6px 0;font-size:13px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;padding:24px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.summary strong{font:700 22px Space,sans-serif}.summary p{font-size:15px;margin:6px 0}.summary em{font-style:normal;color:var(--blue)}section{padding:54px 0;scroll-margin-top:20px}h2{font:700 clamp(36px,4vw,58px)/1.03 Space,sans-serif;letter-spacing:-.04em;margin:12px 0 22px}.section-intro{max-width:850px;margin-bottom:30px}.references{display:grid;grid-template-columns:1fr 1fr;gap:30px}.ref{border-top:2px solid var(--ink);padding-top:14px}.ref video{width:100%;height:300px;object-fit:contain;background:var(--bright);border-radius:8px}.ref h3{font:700 25px Space,sans-serif;margin:18px 0 8px}.ref p{font-size:15px;margin:8px 0}.story{display:grid;grid-template-columns:1fr 1fr;gap:34px}.shot{border-top:2px solid var(--ink);padding-top:14px}.meta{display:flex;justify-content:space-between;gap:12px;font-size:13px;margin:0 0 14px}.frame{aspect-ratio:16/9;border-radius:8px;overflow:hidden;background:var(--bright)}.title-frame,.end-frame,.privacy-frame,.product-frame{width:100%;height:100%;position:relative;display:flex;align-items:center;justify-content:center}.title-frame p{position:absolute;left:8%;top:9%;font:700 clamp(36px,5vw,70px)/1 Space,sans-serif;letter-spacing:-.05em;margin:0}.title-frame p span{color:var(--blue)}.title-frame img{position:absolute;right:7%;bottom:12%;width:35%}.product-frame{padding:24px;background:#e8e7df}.product-frame img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 5px 8px #0002)}.privacy-frame{background:var(--blue);color:white;flex-direction:column;align-items:flex-start;padding:7%;gap:7%}.privacy-frame p{font:700 clamp(22px,3vw,40px)/1.13 Space,sans-serif;margin:0;letter-spacing:-.04em}.privacy-frame small{max-width:85%;font-size:clamp(13px,1.4vw,20px);line-height:1.3}.end-frame{flex-direction:column;gap:14px}.end-frame img{width:40%;height:auto}.end-frame p{font:700 26px Space,sans-serif;margin:0}.end-frame small{font-size:14px}.shot h3{font:700 25px/1.15 Space,sans-serif;letter-spacing:-.03em;margin:16px 0 8px}.shot > p,.shot details p{font-size:15px;margin:8px 0}.shot details{font-size:14px;margin-top:12px}summary{cursor:pointer;min-height:30px}.vo{border-left:2px solid var(--blue);padding-left:14px}.atlas{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.crop{text-decoration:none;border-top:1px solid var(--line);padding-top:12px;min-width:0}.crop img{display:block;width:100%;height:150px;object-fit:contain;background:var(--bright);border-radius:5px}.crop span{display:block;font-size:15px;margin-top:10px}.crop small{color:#646a60;margin-left:8px}.system{display:grid;grid-template-columns:1fr 1fr;gap:40px}.type-box{background:var(--bright);border-radius:8px;padding:32px}.type-box .display{font:700 48px/1 Space,sans-serif;letter-spacing:-.04em;margin:16px 0 24px}.type-box .body{font-size:22px;line-height:1.35}.swatches{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.swatch{height:80px;border-radius:5px;border:1px solid var(--line)}.swatches small{font-size:12px}.notice{background:#e8eeff;padding:24px 30px;border-radius:8px}.notice p{margin:7px 0}.docs{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:28px 0}.docs a{display:block;border-top:1px solid var(--line);padding-top:16px}footer{border-top:1px solid var(--line);padding:24px 0 40px;display:flex;justify-content:space-between;gap:24px;font-size:13px}
@media(max-width:900px){.wrap{padding:0 24px}.hero{grid-template-columns:1fr 1fr;gap:24px}.hero h1{font-size:70px}.hero-visual{padding:20px}.summary{gap:20px}.atlas{grid-template-columns:1fr 1fr}.system{grid-template-columns:1fr}.ref video{height:240px}.end-frame p{font-size:20px}.end-frame small{font-size:12px}}
@media(max-width:620px){header{align-items:flex-start;flex-direction:column;gap:16px}nav{gap:18px}.hero,.references,.story,.system,.docs{grid-template-columns:1fr}.hero{padding-top:36px}.hero h1{font-size:76px}.hero-visual{padding:30px}.summary{grid-template-columns:1fr}.atlas{grid-template-columns:1fr 1fr;gap:16px}.crop img{height:120px}.meta{font-size:12px}.title-frame p{font-size:54px}.privacy-frame p{font-size:30px}.privacy-frame small{font-size:16px}.end-frame p{font-size:24px}footer{flex-direction:column}section{padding:40px 0}}
'''
page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ichido · 55-second promo plan</title><style>{styles}</style></head><body><div class="wrap">
<header><a class="brand" href="#">ichido<span>.</span></a><nav aria-label="Review sections"><a href="#references">References</a><a href="#story">Story</a><a href="#assets">Assets</a><a href="#handoff">Handoff</a></nav></header>
<main><div class="hero"><div><p class="eyebrow">Promo preparation · Revision 2 · 4 October 2026</p><h1>One more<br><span>try.</span></h1><p class="intro">A 55-second Ichido product launch and app walkthrough. Precise clicks, real product components, bold phrases—and room to understand the next step.</p><p><span class="pill">45–60s limit</span><span class="pill">1080p · 60 fps</span><span class="pill">Preproduction</span></p><a href="../script.md">Read the tightened script ↗</a></div><div class="hero-visual"><p class="step">01 · Choose a reference</p><div class="pointer-row">{asset('assets/components/home-actions.png','Actual Home action row')}{asset('assets/interaction/cursor.svg','Illustrative pointer overlay','cursor')}</div><p class="arrow">↓</p><p class="step">02 · Listen, then record</p>{asset('assets/components/practice-mode.png','Actual selected Listen & Repeat mode')}<p class="arrow">↓</p><p class="step">03 · Keep another take</p>{asset('assets/components/try-again.png','Actual Try again control')}</div></div>
<div class="summary"><div><strong><em>A</em> · Interaction</strong><p>One control, one action, a clear next state.</p></div><div><strong><em>B</em> · Story &amp; type</strong><p>Meaningful phrase reveals and a decisive close.</p></div><div><strong>Ichido · Evidence</strong><p>Real UI, measured delivery, private practice.</p></div></div>
<section id="references"><p class="eyebrow">The requested mix</p><h2>Click with purpose.<br>Explain as it happens.</h2><p class="section-intro">Local user-supplied references, shown only for review. They do not enter the promo. The breakdown uses sampled frames and transition strips; audio was not auditioned.</p><div class="references"><article class="ref"><video controls preload="metadata" playsinline poster="../reference/style/A/frame-006.jpg"><source src="../reference/style/reference-A.mp4" type="video/mp4"></video><h3>A · Continuous components</h3><p>Borrow the persistent panel anchor, precise pointer, tab selection and visible response. Keep the stage clean.</p></article><article class="ref"><video controls preload="metadata" playsinline poster="../reference/style/B/frame-005.jpg"><source src="../reference/style/reference-B.mp4" type="video/mp4"></video><h3>B · Type and narrative pace</h3><p>Borrow phrase-based type reveals, purposeful color changes, feature focus and a stable CTA. The ribbon supplies Ichido's identity.</p></article></div><p><a href="../research/reference_videos.md">Read the timecoded breakdown ↗</a></p></section>
<section id="story"><p class="eyebrow">Eight scenes · {TIMELINE['duration_seconds']} seconds · {TIMELINE['duration_frames']} frames</p><h2>The practice loop<br>does the storytelling.</h2><p class="section-intro">Planning panels using actual source pieces. They are not finished motion frames. Fresh response states enable the full click sequence; documented focus/hold fallbacks work with existing assets. French practice, English comparison and ordinary recording are separate examples.</p><div class="story">{''.join(cards)}</div></section>
<section id="assets"><p class="eyebrow">Ready for component animation</p><h2>Eleven exact crops.<br>Three editable layers.</h2><p class="section-intro">No labels, transcripts or values were retouched. Click a crop to inspect its source pixels. Coordinates and pointer targets are in the crop map; cursor, click-ring and focus-outline SVGs are separate editorial layers.</p><div class="atlas">{''.join(atlas)}</div><p><a href="../assets/components/crop-map.json">Crop map ↗</a> · <a href="../assets/interaction/README.md">Interaction layer usage ↗</a> · <a href="../assets_manifest.md">Curated inventory ↗</a></p></section>
<section id="type"><p class="eyebrow">One coherent visual system</p><h2>Paper. Ink. Cobalt.</h2><div class="system"><div class="type-box"><p class="eyebrow">Space Grotesk · 700</p><p class="display">Listen.<br>Repeat.<br>Compare.</p><p class="eyebrow">DM Sans · 400</p><p class="body">A phrase. Your own voice.<br>One more take alongside it.</p></div><div><p>Keep the website's two bundled fonts. Type leads the explanation; the real selected control and its next state carry the response. Interface colors and plot geometry stay faithful.</p><div class="swatches">{''.join(f'<div><div class="swatch" style="background:{color}"></div><small>{name}<br>{color}</small></div>' for name,color in [('Paper','#f4f1e9'),('Ink','#1f241f'),('Cobalt','#2848e8'),('White','#ffffff')])}</div><p>The existing ribbon mark leads. One generated cutout is optional at the bookends; macro, room and night concepts are reserve. No extra image interludes.</p><p><a href="../style_guide.md">Style guide ↗</a></p></div></div></section>
<section id="handoff"><p class="eyebrow">A smaller, concrete production brief</p><h2>Ready for the<br>animation session.</h2><div class="notice"><p><strong>Removed:</strong> the long-film timing, alternate cuts, separate Words/settings/library sections, repeated entry explanations and competing artwork directions.</p><p><strong>Still needed for full actions:</strong> authentic recording, Timing/Emphasis, retry and selected-word playback states. The capture plan gives a fallback for each. BGM, VO and motion remain later work.</p></div><div class="docs">{''.join(f'<a href="../{path}">{label} ↗</a>' for path,label in links)}</div></section></main>
<footer><span>Ichido · Your private speaking room.</span><span>55-second plan · Local preparation · No publication</span></footer></div></body></html>'''
(ROOT / 'review/index.html').write_text(page + '\n')
print(f"Built revision {TIMELINE['revision']} review board from {len(TIMELINE['scenes'])} scenes and {len(CROPS)} crops")
